  "arguments": {
    "expression": "end_2008 - beg_2007",
    "variables": {
      "end_2008": {
        "value": 214.4,
        "source": "source:t8c1n0",
        "unit": "$ millions"
      },
      "beg_2007": {
        "value": 70.5,
        "source": "source:t1c2n0",
        "unit": "$ millions"
      }
    }
  }
}
